cd /data; python3 - <<'E'
def load(f):
    d={}
    for l in open(f):
        l=l.strip()
        if not l or l[0] in '#;': continue
        k,_,v=l.partition('=')
        d[k.strip()]=v.strip()
    return d
a,b=load('v1.conf'),load('v2.conf')
print("Added:")
for k in sorted(b.keys()-a.keys()): print(f"  + {k} = {b[k]}")
print("Removed:")
for k in sorted(a.keys()-b.keys()): print(f"  - {k} (was {a[k]})")
print("Changed:")
for k in sorted(a.keys()&b.keys()):
    if a[k]!=b[k]: print(f"  ~ {k}: {a[k]} -> {b[k]}")
print("Unchanged:", ", ".join(k for k in sorted(a.keys()&b.keys()) if a[k]==b[k]))
